"""Legacy EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


def _is_empty(value: Any) -> bool:
    return value is None or value == ""


def _text(value: Any) -> str:
    return "" if _is_empty(value) else str(value)


def _fixed(value: Any, width: int) -> str:
    return _text(value)[:width].ljust(width)


def _revenue_cents(value: Any) -> int:
    if _is_empty(value):
        value = 0

    decimal_value = Decimal(str(value))
    digits = len(decimal_value.as_tuple().digits)

    with localcontext() as context:
        context.prec = max(28, digits + abs(decimal_value.as_tuple().exponent) + 10)
        cents = decimal_value * Decimal(100)
        return int(cents.to_integral_value(rounding=ROUND_HALF_UP))


def _zpad(value: int, width: int) -> str:
    return str(value).zfill(width)


def format_account(row: dict) -> str:
    """Build one 77-character legacy EXPORT_ACCT record."""
    cred_hold = row.get("CRED_HOLD", "")
    if _is_empty(cred_hold):
        cred_hold = "N"

    create_dt = row.get("CREATE_DT", "")
    if _is_empty(create_dt):
        create_dt = "00000000"

    return (
        _fixed(row.get("ACCT_ID", ""), 10)
        + _fixed(row.get("ACCT_NM", ""), 40)
        + _fixed(row.get("REGION_CD", ""), 3)
        + _zpad(_revenue_cents(row.get("ANN_REV", "")), 15)
        + str(cred_hold)
        + str(create_dt)
    )
